'use client';

import { useEffect, useState } from 'react';

type Theme = 'dark' | 'light';

/**
 * The switch.
 *
 * Three states, not two: until somebody presses it there is no choice
 * stored, and the page follows whatever the phone or laptop is already set
 * to. Pressing it writes a choice, and from then on the site keeps it.
 *
 * The button renders a placeholder until it has read that state on the
 * client. The alternative is guessing on the server and correcting after
 * hydration, which shows the wrong label for a frame - and this label is a
 * claim about what the page is currently doing.
 */
export function ThemeToggle() {
  const [theme, setTheme] = useState<Theme | null>(null);

  useEffect(() => {
    const stored = window.localStorage.getItem('theme');
    if (stored === 'dark' || stored === 'light') {
      setTheme(stored);
      return;
    }
    setTheme(
      window.matchMedia('(prefers-color-scheme: light)').matches ? 'light' : 'dark'
    );
  }, []);

  function flip() {
    const next: Theme = theme === 'light' ? 'dark' : 'light';
    setTheme(next);
    document.documentElement.dataset.theme = next;
    window.localStorage.setItem('theme', next);
  }

  return (
    <button
      type="button"
      onClick={flip}
      aria-label={
        theme ? `Switch to ${theme === 'light' ? 'dark' : 'light'} mode` : 'Switch theme'
      }
      className="label border border-line px-3 py-2 text-dim transition-colors hover:border-hot hover:text-hot"
    >
      {/* Names the ground you would move TO, which is what a switch is for. */}
      <span aria-hidden>{theme === 'light' ? 'Dark' : theme === 'dark' ? 'Light' : '—'}</span>
    </button>
  );
}
